import { EnclosureConfig } from '../types/enclosure';

export function generateScadSource(config: EnclosureConfig): string {
  const effectiveThickness = config.phoneThickness + config.caseAllowance;

  return `// ==============================================================================
// PARAMETRIC DUAL-PURPOSE SMARTPHONE CLOCK ENCLOSURE (TABLE STAND + WALL MOUNT)
// Generated by Web Customizer: https://tumesh007.github.io/phone-wall-clock-enclosure-generator/
// Designed for Bambu Lab A1 mini (180 x 180 x 180 mm build volume) & PETG / PLA
// ==============================================================================

/* [Model Configuration] */
// Select part to render:
// "all_parts_plate"   : Main housing laid out face-down on build plate
// "main_housing"      : Front bezel + phone cradle housing (print face down)
// "backplate"         : Honeycomb back cover with keyholes & 3M pads (print flat)
// "desk_stand"        : Detachable rear wedge stand with cable pass-through (print flat on base)
// "assembly_table"    : Assembled preview in Desk/Table Stand mode (15-deg upright clock)
// "assembly_wall"     : Assembled preview in Flush Wall-Mount mode
part = "${config.viewMode}"; // [all_parts_plate, main_housing, backplate, desk_stand, assembly_table, assembly_wall]

/* [Phone Dimensions (Landscape Orientation)] */
phone_length         = ${config.phoneLength.toFixed(1)}; // Phone length along horizontal X axis [120:200]
phone_width          = ${config.phoneWidth.toFixed(1)};  // Phone width/height along vertical Y axis [60:110]
phone_thickness      = ${effectiveThickness.toFixed(1)};  // Phone thickness including case allowance (${config.caseAllowance.toFixed(1)}mm)
corner_radius        = ${config.cornerRadius.toFixed(1)};  // Phone exterior corner radius

/* [Screen Cutout Dimensions (Front Bezel Window)] */
screen_length        = ${config.screenLength.toFixed(1)}; // Active display length
screen_width         = ${config.screenWidth.toFixed(1)};  // Active display width
screen_corner_radius = ${config.screenCornerRadius.toFixed(1)}; // Screen corner radius
screen_offset_x      = ${config.screenOffsetX.toFixed(1)}; // Horizontal shift if asymmetric
screen_offset_y      = ${config.screenOffsetY.toFixed(1)}; // Vertical shift (e.g. bottom chin)

/* [Tolerances & Walls] */
clearance_tolerance  = ${config.fitTolerance.toFixed(2)};  // Radial fit tolerance around phone perimeter
bezel_lip            = ${config.bezelLip.toFixed(1)};  // Front retention bezel lip over glass edge
wall_thickness       = ${config.wallThickness.toFixed(1)};  // Outer shell wall thickness (PETG recommended: 2.4 - 2.8mm)
front_bezel_thick    = ${config.frontBezelThick.toFixed(1)};  // Front face thickness
corner_rad_enclosure = ${Math.max(config.cornerRadius + 2.0, 6.0).toFixed(1)};

/* [Ports & Audio] */
usb_cutout_width     = ${config.usbWidth.toFixed(1)};  // Cutout width for microUSB / USB-C connector
usb_cutout_height    = ${config.usbHeight.toFixed(1)};   // Cutout height for charging plug
cable_channel_width  = 8.0;   // Recessed channel width for charging cable
cable_channel_depth  = 4.0;   // Recessed channel depth for charging cable
honeycomb_cell_r     = 4.5;   // Radius of honeycomb vent cells
honeycomb_wall       = 1.5;   // Wall thickness between honeycomb cells
usb_side             = "${config.usbSide}"; // Port placement: "right", "left", or "bottom"

/* [Desk Stand & Viewing Angle] */
tilt_angle           = ${config.tiltAngle.toFixed(1)};  // Ergonomic backward viewing tilt angle in degrees
stand_width          = ${config.standWidth.toFixed(1)}; // Width of table stand base
stand_depth          = ${config.standDepth.toFixed(1)};  // Depth of table stand base

/* [Rendering Quality] */
$fn = 48;

// ==============================================================================
// DERIVED INTERNAL DIMENSIONS
// ==============================================================================
cav_x = phone_length + 2 * clearance_tolerance;
cav_y = phone_width + 2 * clearance_tolerance;
cav_z = phone_thickness + 0.5;

outer_x = cav_x + 2 * wall_thickness;
outer_y = cav_y + 2 * wall_thickness;
backplate_thick = 3.6;
outer_z = front_bezel_thick + cav_z + backplate_thick;

win_x = screen_length;
win_y = screen_width;

// ==============================================================================
// TOP-LEVEL PART SELECTOR
// ==============================================================================
if (part == "main_housing") {
    translate([0, 0, outer_z/2])
        rotate([180, 0, 0])
            main_housing();
} else if (part == "backplate") {
    translate([0, 0, backplate_thick/2])
        backplate();
} else if (part == "desk_stand") {
    desk_stand();
} else if (part == "all_parts_plate") {
    plate_layout();
} else if (part == "assembly_table") {
    table_mode_assembly();
} else if (part == "assembly_wall") {
    wall_mode_assembly();
}

// ==============================================================================
// HELPER PRIMITIVES
// ==============================================================================
module rounded_rect_2d(size, r) {
    w = size[0];
    h = size[1];
    actual_r = min(r, min(w/2, h/2));
    hull() {
        translate([-w/2 + actual_r, -h/2 + actual_r]) circle(r=actual_r);
        translate([ w/2 - actual_r, -h/2 + actual_r]) circle(r=actual_r);
        translate([ w/2 - actual_r,  h/2 - actual_r]) circle(r=actual_r);
        translate([-w/2 + actual_r,  h/2 - actual_r]) circle(r=actual_r);
    }
}

module rounded_box(size, r, center=true) {
    w = size[0];
    h = size[1];
    d = size[2];
    actual_r = min(r, min(w/2, h/2));
    if (center) {
        linear_extrude(height=d, center=true)
            rounded_rect_2d([w, h], actual_r);
    } else {
        linear_extrude(height=d)
            rounded_rect_2d([w, h], actual_r);
    }
}

module keyhole_slot(depth=3.0) {
    union() {
        cylinder(d=8.0, h=depth + 0.2, center=true);
        translate([0, 7.0/2, 0])
            cube([4.0, 7.0, depth + 0.2], center=true);
        translate([0, 7.0, 0])
            cylinder(d=4.0, h=depth + 0.2, center=true);
    }
}

// ==============================================================================
// MODULE 1: MAIN HOUSING
// ==============================================================================
module main_housing() {
    difference() {
        union() {
            rounded_box([outer_x, outer_y, outer_z], corner_rad_enclosure, center=true);
            
            translate([0, 0, -outer_z/2 + front_bezel_thick/4])
                rounded_box([outer_x - 1.2, outer_y - 1.2, front_bezel_thick/2], corner_rad_enclosure - 0.6, center=true);
        }

        // Screen viewing window cutout
        translate([screen_offset_x, screen_offset_y, -outer_z/2 + front_bezel_thick/2])
            rounded_box([win_x, win_y, front_bezel_thick + 10.0], screen_corner_radius, center=true);

        // Internal phone cavity
        translate([0, 0, -outer_z/2 + front_bezel_thick + cav_z/2])
            rounded_box([cav_x, cav_y, cav_z + 0.1], corner_radius, center=true);

        // Rear backplate recessed step
        translate([0, 0, outer_z/2 - backplate_thick/2 + 0.05])
            rounded_box([cav_x + 3.6, cav_y + 3.6, backplate_thick + 0.1], corner_radius + 1.8, center=true);

        // Charging port cutout
        if (usb_side == "right") {
            translate([outer_x/2 - wall_thickness/2, 0, -outer_z/2 + front_bezel_thick + cav_z/2])
                cube([wall_thickness * 2 + 1.0, usb_cutout_width, usb_cutout_height], center=true);
        } else if (usb_side == "left") {
            translate([-outer_x/2 + wall_thickness/2, 0, -outer_z/2 + front_bezel_thick + cav_z/2])
                cube([wall_thickness * 2 + 1.0, usb_cutout_width, usb_cutout_height], center=true);
        } else {
            translate([0, -outer_y/2 + wall_thickness/2, -outer_z/2 + front_bezel_thick + cav_z/2])
                cube([usb_cutout_width, wall_thickness * 2 + 1.0, usb_cutout_height], center=true);
        }

        // Loudspeaker perforations
        for (i = [-3: -1: -6]) {
            translate([outer_x/2 - 25.0 + i*4.2, -outer_y/2, -outer_z/2 + front_bezel_thick + cav_z/2])
                rotate([90, 0, 0])
                    cylinder(d=3.0, h=wall_thickness * 2 + 2.0, center=true);
        }

        // Snap-fit retention detents
        for (side = [-1, 1]) {
            translate([0, side * (cav_y/2 + 1.6), outer_z/2 - backplate_thick/2])
                cube([18.0, 0.9, 1.8], center=true);
        }
    }
}

// ==============================================================================
// MODULE 2: HONEYCOMB BACKPLATE
// ==============================================================================
module backplate() {
    bp_x = cav_x + 3.6 - 0.4;
    bp_y = cav_y + 3.6 - 0.4;
    bp_z = backplate_thick;

    difference() {
        union() {
            rounded_box([bp_x, bp_y, bp_z], corner_radius + 1.6, center=true);
            for (side = [-1, 1]) {
                translate([0, side * (bp_y/2 + 0.3), 0])
                    cube([17.0, 0.6, 1.4], center=true);
            }
        }

        // Honeycomb ventilation cells
        step_x = (honeycomb_cell_r * 2 + honeycomb_wall) * cos(30);
        step_y = (honeycomb_cell_r * 2 + honeycomb_wall) * 0.75;
        grid_w = bp_x - 44.0;
        grid_h = bp_y - 20.0;

        for (hx = [-grid_w/2 : step_x : grid_w/2]) {
            for (hy = [-grid_h/2 : step_y*2 : grid_h/2]) {
                translate([hx, hy, 0])
                    rotate([0, 0, 30])
                        cylinder(r=honeycomb_cell_r, h=bp_z + 1.0, center=true, $fn=6);
                translate([hx + step_x/2, hy + step_y, 0])
                    rotate([0, 0, 30])
                        cylinder(r=honeycomb_cell_r, h=bp_z + 1.0, center=true, $fn=6);
            }
        }

        // Dual keyhole wall mounting slots (spaced 80mm)
        for (kx = [-40.0, 40.0]) {
            translate([kx, 4.0, 0])
                keyhole_slot(depth=bp_z);
        }

        // 3M Command strip recessed pockets
        for (cx = [-bp_x/2 + 10.0, bp_x/2 - 10.0]) {
            translate([cx, 0, bp_z/2 - 0.6])
                rounded_box([16.0, 52.0, 1.3], 3.0, center=true);
        }

        // Cable pass-through exit notch
        translate([bp_x/2, 0, 0])
            cube([cable_channel_width, usb_cutout_width + 4.0, bp_z + 1.0], center=true);
    }
}

// ==============================================================================
// MODULE 3: DETACHABLE 15-DEGREE WEDGE DESK STAND
// ==============================================================================
module desk_stand() {
    base_w = stand_width;
    base_d = stand_depth;
    base_h = 42.0;

    difference() {
        translate([0, 0, base_h/2])
            rounded_box([base_w, base_d, base_h], 8.0, center=true);

        translate([0, -base_d/2 + 18.0, base_h - 14.0])
            rotate([-tilt_angle, 0, 0])
                rounded_box([outer_x + 1.6, outer_z + 2.2, 40.0], corner_rad_enclosure, center=true);

        // Rear cable pass-through arch
        translate([0, base_d/2 - 12.0, base_h/2 - 4.0])
            rounded_box([28.0, 26.0, 24.0], 4.0, center=true);

        // Front speaker relief cutouts
        for (sx = [-30.0, 30.0]) {
            translate([sx, -base_d/2 + 6.0, base_h - 10.0])
                rotate([0, 90, 0])
                    cylinder(d=12.0, h=22.0, center=true);
        }

        // Anti-slip rubber feet pockets
        for (fx = [-base_w/2 + 16.0, base_w/2 - 16.0]) {
            for (fy = [-base_d/2 + 12.0, base_d/2 - 12.0]) {
                translate([fx, fy, -0.1])
                    cylinder(d=8.5, h=1.6, center=false, $fn=24);
            }
        }
    }
}

// ==============================================================================
// MODULE 4: PLATE LAYOUT (BAMBU LAB A1 MINI 180 x 180 mm)
// ==============================================================================
module plate_layout() {
    translate([0, 0, outer_z/2])
        rotate([180, 0, 0])
            main_housing();
}

// ==============================================================================
// MODULE 5: ASSEMBLY PREVIEWS
// ==============================================================================
module table_mode_assembly() {
    color("#4A5568") desk_stand();
    translate([0, -stand_depth/2 + 18.0, 10.0])
        rotate([-tilt_angle, 0, 0]) {
            rotate([90, 0, 180]) {
                color("#F7FAFC") main_housing();
                translate([0, 0, outer_z/2 - backplate_thick/2])
                    color("#CBD5E0") backplate();
            }
        }
}

module wall_mode_assembly() {
    translate([0, outer_y/2, outer_z/2]) {
        rotate([90, 0, 180]) {
            color("#F7FAFC") main_housing();
            translate([0, 0, outer_z/2 - backplate_thick/2])
                color("#CBD5E0") backplate();
        }
    }
}
`;
}
